static int mrfld_extcon_sw_control ( struct mrfld_extcon_data * data , bool enable ) { int mask = BCOVE_CHGRCTRL0_SWCONTROL ; struct device * dev = data -> dev ; int ret ; if ( enable ) { ret = mrfld_extcon_set ( data , BCOVE_CHGRCTRL0 , mask ) ; } else { ret = mrfld_extcon_clear ( data , BCOVE_CHGRCTRL0 , mask ) ; } if ( ret ) { dev_err ( dev , "can't set SW control: %d\n" , ret ) ; } return ret ; } 